CREATE TABLE IF NOT EXISTS schema_migrations (version INT PRIMARY KEY, applied_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS organizations (id CHAR(32) PRIMARY KEY, name VARCHAR(180) NOT NULL, demo BOOLEAN NOT NULL, payload JSON NOT NULL);
CREATE TABLE IF NOT EXISTS users (id CHAR(32) PRIMARY KEY, organization_id CHAR(32) NOT NULL, email VARCHAR(254) NOT NULL UNIQUE, payload JSON NOT NULL, FOREIGN KEY (organization_id) REFERENCES organizations(id));
CREATE TABLE IF NOT EXISTS organization_members (organization_id CHAR(32) NOT NULL, user_id CHAR(32) NOT NULL, role VARCHAR(20) NOT NULL DEFAULT 'owner', PRIMARY KEY(organization_id,user_id), FOREIGN KEY(organization_id) REFERENCES organizations(id), FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS sessions (token_hash CHAR(64) PRIMARY KEY, user_id CHAR(32) NOT NULL, payload JSON NOT NULL, FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS clients (id CHAR(32) PRIMARY KEY, organization_id CHAR(32) NOT NULL, name VARCHAR(180) NOT NULL, active BOOLEAN NOT NULL, payload JSON NOT NULL, UNIQUE KEY uq_client_owner(id,organization_id), INDEX idx_clients_org(organization_id,active,name), FOREIGN KEY(organization_id) REFERENCES organizations(id));
CREATE TABLE IF NOT EXISTS document_templates (id CHAR(32) PRIMARY KEY, organization_id CHAR(32) NOT NULL, name VARCHAR(180) NOT NULL, active BOOLEAN NOT NULL, payload JSON NOT NULL, UNIQUE KEY uq_template_owner(id,organization_id), INDEX idx_templates_org(organization_id), FOREIGN KEY(organization_id) REFERENCES organizations(id));
CREATE TABLE IF NOT EXISTS document_template_items (id CHAR(32) PRIMARY KEY, organization_id CHAR(32) NOT NULL, template_id CHAR(32) NOT NULL, position INT NOT NULL, payload JSON NOT NULL, FOREIGN KEY(template_id,organization_id) REFERENCES document_templates(id,organization_id));
CREATE TABLE IF NOT EXISTS recurring_schedules (id CHAR(32) PRIMARY KEY, organization_id CHAR(32) NOT NULL, template_id CHAR(32) NOT NULL, active BOOLEAN NOT NULL, payload JSON NOT NULL, FOREIGN KEY(organization_id) REFERENCES organizations(id), FOREIGN KEY(template_id,organization_id) REFERENCES document_templates(id,organization_id));
CREATE TABLE IF NOT EXISTS document_requests (id CHAR(32) PRIMARY KEY, organization_id CHAR(32) NOT NULL, client_id CHAR(32) NOT NULL, template_id CHAR(32) NOT NULL, competence CHAR(7) NOT NULL, due_date DATE NOT NULL, status VARCHAR(32) NOT NULL, schedule_id CHAR(32) NULL, payload JSON NOT NULL, UNIQUE KEY uq_request_owner(id,organization_id), UNIQUE KEY uniq_schedule_request(schedule_id,client_id,competence), INDEX idx_requests_org_status_due(organization_id,status,due_date), INDEX idx_requests_client(organization_id,client_id,competence), FOREIGN KEY(organization_id) REFERENCES organizations(id), FOREIGN KEY(client_id,organization_id) REFERENCES clients(id,organization_id));
CREATE TABLE IF NOT EXISTS document_request_items (id CHAR(32) PRIMARY KEY, organization_id CHAR(32) NOT NULL, request_id CHAR(32) NOT NULL, position INT NOT NULL, status VARCHAR(32) NOT NULL, payload JSON NOT NULL, UNIQUE KEY uq_item_owner(id,organization_id), FOREIGN KEY(request_id,organization_id) REFERENCES document_requests(id,organization_id));
CREATE TABLE IF NOT EXISTS document_files (id CHAR(32) PRIMARY KEY, organization_id CHAR(32) NOT NULL, item_id CHAR(32) NOT NULL, object_key VARCHAR(300) NOT NULL UNIQUE, scan_status VARCHAR(40) NOT NULL, payload JSON NOT NULL, FOREIGN KEY(organization_id) REFERENCES organizations(id), FOREIGN KEY(item_id,organization_id) REFERENCES document_request_items(id,organization_id));
CREATE TABLE IF NOT EXISTS public_access_tokens (token_hash CHAR(64) PRIMARY KEY, organization_id CHAR(32) NOT NULL, request_id CHAR(32) NOT NULL, payload JSON NOT NULL, FOREIGN KEY(organization_id) REFERENCES organizations(id), FOREIGN KEY(request_id,organization_id) REFERENCES document_requests(id,organization_id));
CREATE TABLE IF NOT EXISTS recurring_schedule_runs (id CHAR(32) PRIMARY KEY, organization_id CHAR(32) NOT NULL, schedule_id CHAR(32) NOT NULL, client_id CHAR(32) NOT NULL, competence CHAR(7) NOT NULL, request_id CHAR(32) NOT NULL, payload JSON NOT NULL, UNIQUE KEY uniq_schedule_run(schedule_id,client_id,competence), FOREIGN KEY(schedule_id) REFERENCES recurring_schedules(id));
CREATE TABLE IF NOT EXISTS notification_deliveries (id CHAR(32) PRIMARY KEY, organization_id CHAR(32) NOT NULL, request_id CHAR(32) NOT NULL, status VARCHAR(32) NOT NULL, payload JSON NOT NULL, INDEX idx_delivery_org(organization_id,request_id), FOREIGN KEY(organization_id) REFERENCES organizations(id));
CREATE TABLE IF NOT EXISTS audit_events (id CHAR(32) PRIMARY KEY, organization_id CHAR(32) NOT NULL, action VARCHAR(80) NOT NULL, entity_id CHAR(32) NOT NULL, payload JSON NOT NULL, INDEX idx_audit_org(organization_id), FOREIGN KEY(organization_id) REFERENCES organizations(id));
CREATE TABLE IF NOT EXISTS password_resets (token_hash CHAR(64) PRIMARY KEY, user_id CHAR(32) NOT NULL, payload JSON NOT NULL, FOREIGN KEY(user_id) REFERENCES users(id));
